#include <bits/stdc++.h>
using namespace std;
typedef complex<double> cd;
const double PI = acos(-1.0);

void fft(vector<cd>& a, bool invert) {
    int n = a.size();
    if (n == 1) return;
    for (int i = 1, j = 0; i < n; i++) {
        int bit = n >> 1;
        for (; j & bit; bit >>= 1) j ^= bit;
        j ^= bit;
        if (i < j) swap(a[i], a[j]);
    }
    for (int len = 2; len <= n; len <<= 1) {
        double ang = 2 * PI / len * (invert ? -1 : 1);
        cd wlen(cos(ang), sin(ang));
        for (int i = 0; i < n; i += len) {
            cd w(1);
            for (int j = 0; j < len / 2; j++) {
                cd u = a[i + j];
                cd v = a[i + j + len / 2] * w;
                a[i + j] = u + v;
                a[i + j + len / 2] = u - v;
                w *= wlen;
            }
        }
    }
    if (invert) {
        for (cd& x : a) x /= n;
    }
}

vector<long long> multiply(vector<long long> const& a, vector<long long> const& b) {
    vector<cd> fa(a.begin(), a.end()), fb(b.begin(), b.end());
    int resultSize = (int)a.size() + (int)b.size() - 1;
    int n = 1;
    while (n < resultSize) n <<= 1;
    fa.resize(n);
    fb.resize(n);
    fft(fa, false);
    fft(fb, false);
    for (int i = 0; i < n; i++) fa[i] *= fb[i];
    fft(fa, true);
    vector<long long> result(resultSize);
    for (int i = 0; i < resultSize; i++) result[i] = llround(fa[i].real());
    return result;
}

int main() {
    int sizeA, sizeB;
    cin >> sizeA >> sizeB;
    vector<long long> a(sizeA), b(sizeB);
    for (auto& x : a) cin >> x;
    for (auto& x : b) cin >> x;
    vector<long long> c = multiply(a, b);
    cout << c.size() << "\n";
    for (int i = 0; i < (int)c.size(); i++) {
        cout << c[i] << (i + 1 < (int)c.size() ? ' ' : '\n');
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll MOD = 998244353;
const ll ROOT = 3; // a primitive root modulo 998244353

ll power(ll a, ll b, ll mod) {
    a %= mod;
    if (a < 0) a += mod;
    ll res = 1;
    while (b > 0) {
        if (b & 1) res = res * a % mod;
        a = a * a % mod;
        b >>= 1;
    }
    return res;
}

void ntt(vector<ll>& a, bool invert) {
    int n = (int)a.size();
    for (int i = 1, j = 0; i < n; i++) {
        int bit = n >> 1;
        for (; j & bit; bit >>= 1) j ^= bit;
        j ^= bit;
        if (i < j) swap(a[i], a[j]);
    }
    for (int len = 2; len <= n; len <<= 1) {
        ll w = invert ? power(ROOT, MOD - 1 - (MOD - 1) / len, MOD)
                      : power(ROOT, (MOD - 1) / len, MOD);
        for (int i = 0; i < n; i += len) {
            ll wn = 1;
            for (int j = 0; j < len / 2; j++) {
                ll u = a[i + j];
                ll v = a[i + j + len / 2] * wn % MOD;
                a[i + j] = (u + v) % MOD;
                a[i + j + len / 2] = (u - v + MOD) % MOD;
                wn = wn * w % MOD;
            }
        }
    }
    if (invert) {
        ll n_inv = power(n, MOD - 2, MOD);
        for (ll& x : a) x = x * n_inv % MOD;
    }
}

vector<ll> multiply(vector<ll> a, vector<ll> b) {
    int resultSize = (int)a.size() + (int)b.size() - 1;
    int n = 1;
    while (n < resultSize) n <<= 1;
    a.resize(n);
    b.resize(n);
    ntt(a, false);
    ntt(b, false);
    for (int i = 0; i < n; i++) a[i] = a[i] * b[i] % MOD;
    ntt(a, true);
    a.resize(resultSize);
    return a;
}

int main() {
    int sizeA, sizeB;
    cin >> sizeA >> sizeB;
    vector<ll> a(sizeA), b(sizeB);
    for (auto& x : a) cin >> x;
    for (auto& x : b) cin >> x;
    vector<ll> c = multiply(a, b);
    cout << c.size() << "\n";
    for (size_t i = 0; i < c.size(); i++) {
        cout << c[i] << (i + 1 < c.size() ? ' ' : '\n');
    }
    return 0;
}
